-- Compiles and embeds Lua source files directly into C89 byte arrays,
-- using an ERB-style template engine for high clarity and customizability.

import("template")

local DEFAULT_BUNDLE_TEMPLATE = [[
/* Generated by Projectum Lunare Forge Bundler */
/* Standard ANSI C89 / ISO C90 */

#ifdef __cplusplus
extern "C" {
#endif
#include <lua.h>
#include <lauxlib.h>
#include <lualib.h>
#ifdef __cplusplus
}
#endif
#include <stdio.h>
#include <stdlib.h>

<% for _, mod in ipairs(modules) do %>
/* Module: <%= mod.name %> (<%= mod.relpath %>) */
static const unsigned char <%= mod.varname %>[] = {
<%= mod.hex_bytes %>
};

static int <%= mod.loader %>(lua_State *L) {
    if (luaL_loadbuffer(L, (const char *)<%= mod.varname %>, sizeof(<%= mod.varname %>), "@<%= mod.relpath %>") != LUA_OK) {
        return lua_error(L);
    }
    lua_call(L, 0, 1);
    return 1;
}
<% end %>

void forge_lua_preload_all(lua_State *L) {
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "preload");
<% for _, mod in ipairs(modules) do %>
    lua_pushcfunction(L, <%= mod.loader %>);
    lua_setfield(L, -2, "<%= mod.name %>");
<% end %>
    lua_pop(L, 2);
}

<% if include_main then %>
int main(int argc, char **argv) {
    lua_State *L = luaL_newstate();
    int i, status;
    if (!L) {
        fprintf(stderr, "[forge] Error: Failed to initialize Lua runtime.\n");
        return 1;
    }
    luaL_openlibs(L);
    forge_lua_preload_all(L);

    /* Push arguments into arg table */
    lua_createtable(L, argc - 1, 1);
    for (i = 0; i < argc; i++) {
        lua_pushstring(L, argv[i]);
        lua_rawseti(L, -2, i);
    }
    lua_setglobal(L, "arg");

    /* Execute entry module '<%= entry_module %>' via require */
    lua_getglobal(L, "require");
    lua_pushstring(L, "<%= entry_module %>");
    status = lua_pcall(L, 1, 0, 0);
    if (status != LUA_OK) {
        const char *err = lua_tostring(L, -1);
        fprintf(stderr, "[forge] Runtime error: %s\n", err ? err : "unknown");
        lua_close(L);
        return 1;
    }
    lua_close(L);
    return 0;
}
<% end %>
]]

-- Format raw file bytes into formatted C hex array lines
local function bytes_to_c_hex(content)
    local hex_lines = {}
    local current_line = {}
    for b in content:gmatch(".") do
        table.insert(current_line, string.format("0x%02x", string.byte(b)))
        if #current_line >= 16 then
            table.insert(hex_lines, "    " .. table.concat(current_line, ", "))
            current_line = {}
        end
    end
    if #current_line > 0 then
        table.insert(hex_lines, "    " .. table.concat(current_line, ", "))
    end
    return table.concat(hex_lines, ",\n")
end

function generate_bundle_source(files, opt)
    opt = opt or {}
    local entry_module = opt.entry_module or "main"
    local modules = {}

    for idx, f in ipairs(files) do
        local content = io.readfile(f)
        if content then
            local relpath = opt.file_map and opt.file_map[f] or path.filename(f)
            local modname = relpath:gsub("%.lua$", ""):gsub("/", "."):gsub("\\", ".")
            if modname:endswith(".init") then
                modname = modname:sub(1, -6)
            end

            table.insert(modules, {
                id = idx,
                name = modname,
                relpath = relpath,
                varname = "forge_lua_data_" .. idx,
                loader = "forge_preload_" .. idx,
                hex_bytes = bytes_to_c_hex(content)
            })
        end
    end

    local context = {
        modules = modules,
        entry_module = entry_module,
        include_main = opt.include_main ~= false
    }

    if opt.template_file and os.isfile(opt.template_file) then
        return template.render_file(opt.template_file, context)
    else
        return template.render(DEFAULT_BUNDLE_TEMPLATE, context)
    end
end
